/*
 * 资料的“已读”标签页：此人读过的主题，从最新到最旧
 *（`filter[lcoyReadBy]`，来自 extend/activity.php），使用常规的主题列表。
 * 仅本人和管理员可见；服务器会再次校验。
 */
import UserPage from 'flarum/forum/components/UserPage';
import DiscussionList from 'flarum/forum/components/DiscussionList';
import DiscussionListState from 'flarum/forum/states/DiscussionListState';
import { leaveIfHidden } from './install';
export default class ReadUserPage extends UserPage {
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    if (leaveIfHidden('read', user)) return;
    super.show(user);
    this.state = new DiscussionListState({
      filter: {
        lcoyReadBy: user.slug()
      }
    });
    this.state.refresh();
  }
  content() {
    return m("div", {
      className: "DiscussionsUserPage LcoyReadUserPage"
    }, this.state && m(DiscussionList, {
      state: this.state
    }));
  }
}
flarum.reg.add('lcoy-roselle', 'forum/user/activity/ReadUserPage', ReadUserPage);